-- Database: `siprs_unit_pejabat`
-- Data Master: Seluruh Unit & Kepala / Penanggung Jawab Ruangan RSUD Koesnandi
CREATE DATABASE IF NOT EXISTS `siprs_unit_pejabat` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `siprs_unit_pejabat`;

DROP TABLE IF EXISTS `unit_penanggung_jawab`;

CREATE TABLE `unit_penanggung_jawab` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nama_unit` VARCHAR(150) NOT NULL,
    `kategori` VARCHAR(100) NOT NULL,
    `penanggung_jawab` VARCHAR(150) NOT NULL,
    `nip` VARCHAR(50) DEFAULT '-',
    `nik` VARCHAR(50) DEFAULT '-',
    `email` VARCHAR(100) DEFAULT '-',
    `jabatan_pj` VARCHAR(255) DEFAULT '-',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

